const FALLBACK = "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><ellipse cx=\"12\" cy=\"6\" rx=\"6\" ry=\"2.6\"/><path d=\"M6 6v12c0 1.44 2.69 2.6 6 2.6s6-1.16 6-2.6V6\"/></svg>";

const PANEL = /<ul class="sub-menu">[\s\S]*?<\/ul>/g;
const LINK = /<a href="[^"]*\/product\/([a-z0-9-]+)\/"[^>]*>/g;

/** Put a product icon in front of every dropdown link. */
export function withMenuIcons(html) {
  return html.replace(PANEL, (panel) =>
    panel.replace(LINK, (tag, slug) =>
      `${tag}<span class="tpm-mi" aria-hidden="true">${ICONS[slug] || FALLBACK}</span>`
    )
  );
}
